#!/usr/bin/env node
/**
 * Bundle Carbon's PebbleKit JS weather code (src/pkjs/weather/) for the
 * Android widget. The watchface sources stay the single source of truth:
 * this script never copies them into the repo, it writes one generated file
 * (default: app/build/generated/carbonJs/carbon-weather.js) that Gradle adds
 * to the APK's assets.
 *
 * A tiny CommonJS bundler (no npm deps): starts at widget-entry.js, follows
 * relative require('./x') calls, wraps each module in a function.
 *
 * Usage: node tools/bundle-pkjs.js [outFile]
 */
'use strict';
var fs = require('fs');
var path = require('path');

var ENTRY = path.join(__dirname, 'widget-entry.js');
var ROOT = path.resolve(__dirname, '..', '..');
var OUT = path.resolve(process.argv[2] || path.join(__dirname, '..', 'app', 'build', 'generated', 'carbonJs', 'carbon-weather.js'));

function resolve(fromFile, req) {
	if (!/^\.\.?\//.test(req)) throw new Error('only relative requires are bundled: ' + req + ' in ' + fromFile);
	var base = path.resolve(path.dirname(fromFile), req);
	var tries = [base, base + '.js', path.join(base, 'index.js')];
	for (var i = 0; i < tries.length; i++) if (fs.existsSync(tries[i]) && fs.statSync(tries[i]).isFile()) return tries[i];
	throw new Error('cannot resolve ' + req + ' from ' + fromFile);
}

var ids = {}, order = [];
function add(file) {
	if (ids[file] !== undefined) return ids[file];
	var id = order.length;
	ids[file] = id;
	var mod = { file: file, src: fs.readFileSync(file, 'utf8'), deps: {} };
	order.push(mod);
	var re = /\brequire\(\s*['"]([^'"]+)['"]\s*\)/g, m;
	while ((m = re.exec(mod.src))) mod.deps[m[1]] = add(resolve(file, m[1]));
	return id;
}
add(ENTRY);

var out = [];
out.push('/* GENERATED by android/tools/bundle-pkjs.js from src/pkjs. Do not edit. */');
out.push('(function () {');
out.push('var __defs = [');
order.forEach(function (mod, i) {
	out.push('/* ' + path.relative(ROOT, mod.file) + ' */');
	out.push('[function (require, module, exports) {\n' + mod.src + '\n}, ' + JSON.stringify(mod.deps) + ']' + (i < order.length - 1 ? ',' : ''));
});
out.push('];');
out.push('var __cache = {};');
out.push('function __req(id) {');
out.push('  if (__cache[id]) return __cache[id].exports;');
out.push('  var m = __cache[id] = { exports: {} }, d = __defs[id];');
out.push('  d[0](function (n) { if (!(n in d[1])) throw new Error("not bundled: " + n); return __req(d[1][n]); }, m, m.exports);');
out.push('  return m.exports;');
out.push('}');
out.push('__req(0);');
out.push('})();');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, out.join('\n') + '\n');
console.log('bundled ' + order.length + ' modules -> ' + path.relative(process.cwd(), OUT));
order.forEach(function (m) { console.log('  ' + path.relative(ROOT, m.file)); });
